/**
 * Oauth Login Callback Get
 * Handle the OAuth redirect from the provider and set a session.
 *
 * If the provider denies access (e.g. the user declines), it redirects back
 * with `error`/`error_description` query params instead of `code`. In that
 * case we forward the error to the frontend rather than processing a token.
 *
 * All internal failures (invalid state, token exchange 401, userinfo
 * extraction, etc.) are also redirected to the frontend's
 * ``oauth_redirect_url`` with ``?status=error&error=...`` instead of
 * returning a raw 400/500 JSON. This matches the browser-redirect UX:
 * the frontend can show the error details instead of a blank error page.
 * The JSON ``POST /api/oauth/login/callback`` still returns 400/500 for API clients.
 *
 * When ``state`` carries ``mode == "link"`` the flow attaches the provider
 * identity to the currently authenticated user (link flow) instead of
 * logging in, and redirects to the profile page. This keeps a single
 * ``redirect_uri`` registered with the provider for both flows.
 */
export const oauthLoginCallbackGetApiOauthLoginCallbackGetOptions = (options?: Options<OauthLoginCallbackGetApiOauthLoginCallbackGetData>) => {
    return queryOptions({
        queryFn: async ({ queryKey, signal }) => {
            const { data } = await oauthLoginCallbackGetApiOauthLoginCallbackGet({
                ...options,
                ...queryKey[0],
                signal,
                throwOnError: true
            });
            return data;
        },
        queryKey: oauthLoginCallbackGetApiOauthLoginCallbackGetQueryKey(options)
    });
};

